content.text:
Now replace the touch binding block. Current block:

```js
document.querySelectorAll('[data-hold]').forEach(btn=>{const k=btn.dataset.hold;const down=e=>{e.preventDefault();btn.classList.add('on');if(k==='space'){pressHit();keys[' ']=true}else if(k==='e')dash();else if(k==='q')well();else keys[k]=true};const up=e=>{e.preventDefault();btn.classList.remove('on');keys[k==='space'?' ':k]=false};btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointercancel',up);btn.addEventListener('pointerleave',up)});
```

Replace with new handlers including analog move zone, dash/well/jump buttons, contextmenu prevention. Note: drag zone uses pointer capture; also need to prevent scroll/pinch: touch-action none already.

Also `pressHit` when overlay visible? Buttons hidden behind overlay (z-index 20). Good.

Implementation:

```js
const moveZone=document.querySelector('#moveZone'),moveKnob=document.querySelector('#moveKnob');
function setTouchMove(v){touchMove=THREE.MathUtils.clamp(v,-1,1);const limit=Math.max(20,moveZone.clientWidth*.22);moveKnob.style.transform=`translateX(${touchMove*limit}px)`}
function zoneDir(e){const r=moveZone.getBoundingClientRect();return (e.clientX-(r.left+r.width/2))/(r.width*.3)}
moveZone.addEventListener('pointerdown',e=>{e.preventDefault();if(touchPointer!==null)return;touchPointer=e.pointerId;try{moveZone.setPointerCapture(e.pointerId)}catch(err){}moveZone.classList.add('on');setTouchMove(zoneDir(e))});
moveZone.addEventListener('pointermove',e=>{if(e.pointerId!==touchPointer)return;e.preventDefault();setTouchMove(zoneDir(e))});
const endMove=e=>{if(e.pointerId!==touchPointer)return;touchPointer=null;moveZone.classList.remove('on');setTouchMove(0)};
['pointerup','pointercancel','lostpointercapture'].forEach(t=>moveZone.addEventListener(t,endMove));
function bindAction(sel,fn){const b=document.querySelector(sel);if(!b)return;b.addEventListener('pointerdown',e=>{e.preventDefault();b.classList.add('on');fn()});['pointerup','pointercancel','pointerleave'].forEach(t=>b.addEventListener(t,e=>{e.preventDefault();b.classList.remove('on')}))}
bindAction('#dashBtn',dash);bindAction('#wellBtn',well);
const jumpBtn=document.querySelector('#jumpBtn');
jumpBtn.addEventListener('pointerdown',e=>{e.preventDefault();jumpBtn.classList.add('on');keys[' ']=true;pressHit()});
['pointerup','pointercancel','pointerleave'].forEach(t=>jumpBtn.addEventListener(t,e=>{e.preventDefault();jumpBtn.classList.remove('on');keys[' ']=false}));
document.addEventListener('contextmenu',e=>e.preventDefault());
```

Note `bindAction` selector querySelector with '#dashBtn' fine.

Potential conflict: pointerleave after pointerdown on jump resets; but pointer capture? Buttons don't set capture; pointerleave may fire when finger slides. Fine.

One issue: move zone uses `lostpointercapture` which fires after pointerup too; endMove handles null check.

Now replace.

