  await p.waitForTimeout(120);console.log(name,'knob slide left:',await p.locator('#moveKnob').evaluate(x=>x.style.transform));
  await p.locator('#moveZone').dispatchEvent('pointerup',{pointerId:9,clientX:z.x+z.width*0.15,clientY:y,pointerType:'touch',isPrimary:true,bubbles:true});
  await p.waitForTimeout(80);console.log(name,'knob release:',await p.locator('#moveKnob').evaluate(x=>x.style.transform));
  await p.locator('#jumpBtn').tap();await p.waitForTimeout(1200);
  await p.locator('#dashBtn').tap();await p.locator('#wellBtn').tap();await p.waitForTimeout(200);
  console.log(name,'dash/well:',await p.locator('#dashBtn').getAttribute('class'),'/',await p.locator('#wellBtn').getAttribute('class'),'game classes:',await p.locator('#mobile').evaluate(x=>getComputedStyle(x).display),'errs',errs.length);
